import { ClioNowPlaying } from "@/components/application/clio/now-playing";
import { ClioTheme } from "@/components/application/clio/theme";

export default function ClioNowPlayingDemo() {
  return (
    <ClioTheme
      style={{
        display: "grid",
        placeItems: "center",
        width: "100%",
        padding: 32,
        borderRadius: 24,
      }}
    >
      <ClioNowPlaying
        label="Listening"
        title="A short history of the index card"
        source="Read aloud from your saves"
        duration={700}
        defaultPosition={252}
        style={{ width: "min(100%, 440px)", height: 220 }}
      />
    </ClioTheme>
  );
}

