"use client";
/**
 * Clio now playing: a cover, a title, a playhead that moves while it plays, and back, play and forward buttons. The
 * track is a slider: drag it, click it or use the arrow keys.
 */
import {
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { ClioTile, type ClioTileProps, useClioReducedMotion } from "./theme";

const CSS = `
.clio-play__body{margin-top:auto;display:flex;align-items:stretch;gap:14px;padding-top:12px;min-width:0}
.clio-play__cover{position:relative;flex:none;width:var(--clio-play-cover,104px);aspect-ratio:1;border-radius:var(--clio-radius-inner);overflow:hidden;background:var(--clio-raised);box-shadow:var(--clio-shadow-raised),0 0 0 1px var(--clio-hairline);transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play__cover svg{display:block;width:100%;height:100%}
.clio-play__main{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:flex-end;gap:7px}
.clio-play__title{margin:0;font-size:14px;font-weight:500;line-height:1.25;letter-spacing:-.01em;color:var(--clio-ink);overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.clio-play__track{position:relative;height:16px;margin:4px 0 0;cursor:pointer;touch-action:none;border-radius:6px}
.clio-play__track:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-play__rail{position:absolute;left:0;right:0;top:7px;height:2px;border-radius:1px;background:var(--clio-track);overflow:hidden;transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play__fill{position:absolute;inset:0;background:var(--clio-ink);transform-origin:0 50%;transform:scaleX(var(--clio-play-at,0));transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play__head{position:absolute;top:3px;left:0;width:10px;height:10px;margin-left:-5px;border-radius:999px;background:var(--clio-accent);box-shadow:0 0 0 3px var(--clio-tile);transform:translate3d(var(--clio-play-x,0px),0,0);transition:box-shadow var(--clio-mode-ms) var(--clio-mode-ease),background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play__track[data-seeking] .clio-play__head{transform:translate3d(var(--clio-play-x,0px),0,0) scale(1.25)}
.clio-play__times{display:flex;justify-content:space-between;font-variant-numeric:tabular-nums}
.clio-play__controls{display:flex;align-items:center;gap:6px;margin-top:2px}
.clio-play__btn{all:unset;display:inline-grid;place-items:center;width:32px;height:32px;border-radius:999px;cursor:pointer;color:var(--clio-ink);transition:background-color 160ms ease,transform var(--clio-press-ms) var(--clio-press-ease),color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play__btn:hover{background:var(--clio-track)}
.clio-play__btn:active{transform:scale(.92)}
.clio-play__btn:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-play__btn svg{width:18px;height:18px}
.clio-play__btn[data-main]{width:36px;height:36px;background:var(--clio-ink);color:var(--clio-tile)}
.clio-play__btn[data-main]:hover{background:var(--clio-ink-secondary)}
.clio-play__levels{display:inline-flex;align-items:flex-end;gap:2px;height:12px}
.clio-play__levels i{display:block;width:2px;height:100%;border-radius:1px;background:var(--clio-accent-ink);transform-origin:50% 100%;transform:scaleY(.35);transition:background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-play[data-playing] .clio-play__levels i{animation:clio-play-level 1.1s ease-in-out infinite alternate}
.clio-play__levels i:nth-child(2){animation-delay:-.45s!important}
.clio-play__levels i:nth-child(3){animation-delay:-.8s!important}
@keyframes clio-play-level{0%{transform:scaleY(.3)}35%{transform:scaleY(.95)}70%{transform:scaleY(.5)}100%{transform:scaleY(.8)}}
@container (max-width:300px){.clio-play__cover{--clio-play-cover:76px}}
@media (prefers-reduced-motion:reduce){.clio-play[data-playing] .clio-play__levels i{animation:none;transform:scaleY(.6)}}
`;

/** Seconds as mm:ss (or h:mm:ss from an hour), e.g. 252 → "04:12". Anything not a positive number is "00:00". */
export function clioFormatClock(seconds: number): string {
  const s = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const pad = (n: number) => String(n).padStart(2, "0");
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  return h > 0 ? `${h}:${pad(m)}:${pad(s % 60)}` : `${pad(m)}:${pad(s % 60)}`;
}

/** Where the playhead sits, 0–1, for a position in a track of `duration` seconds. */
export function clioPlayhead(position: number, duration: number): number {
  if (!(duration > 0) || !Number.isFinite(position)) return 0;
  return Math.min(1, Math.max(0, position / duration));
}

/** The position `elapsed` seconds on, stopped at the end. */
export function clioAdvance(
  position: number,
  elapsed: number,
  duration: number,
): { position: number; ended: boolean } {
  const end = Math.max(0, duration);
  const next = Math.min(end, Math.max(0, position + Math.max(0, elapsed)));
  return { position: next, ended: next >= end };
}

/** A saved page, ruled, with a ribbon marking the place: the cover when none is given. */
export function ClioPaperCover({ title = "" }: { title?: string }) {
  return (
    <svg viewBox="0 0 100 100" role="img" aria-label={title ? `Cover for ${title}` : "Cover"}>
      <rect width="100" height="100" fill="var(--clio-raised)" />
      <path
        d="M18 14h52l14 14v58H18z"
        fill="var(--clio-tile)"
        stroke="var(--clio-hairline-strong)"
        strokeWidth="1"
      />
      <path d="M70 14v14h14" fill="none" stroke="var(--clio-hairline-strong)" strokeWidth="1" />
      {[38, 47, 56, 65, 74].map((y, i) => (
        <line
          key={y}
          x1="26"
          x2={i === 4 ? 58 : 76}
          y1={y}
          y2={y}
          stroke="var(--clio-bar)"
          strokeOpacity={0.55}
          strokeWidth="1.6"
          strokeLinecap="round"
        />
      ))}
      <path d="M28 14v22l6-5 6 5V14z" fill="var(--clio-accent)" />
    </svg>
  );
}

const Icon = ({ d }: { d: string }) => (
  <svg viewBox="0 0 18 18" aria-hidden="true">
    <path d={d} fill="currentColor" />
  </svg>
);
const PLAY = "M6.2 3.9v10.2c0 .6.6.9 1.1.6l8-5.1c.5-.3.5-.9 0-1.2l-8-5.1c-.5-.3-1.1 0-1.1.6z";
const PAUSE =
  "M5.2 3.5h2.4c.3 0 .5.2.5.5v10c0 .3-.2.5-.5.5H5.2a.5.5 0 0 1-.5-.5V4c0-.3.2-.5.5-.5zm5.2 0h2.4c.3 0 .5.2.5.5v10c0 .3-.2.5-.5.5h-2.4a.5.5 0 0 1-.5-.5V4c0-.3.2-.5.5-.5z";
const BACK =
  "M9 3.2a5.8 5.8 0 1 1-5.6 7.3.7.7 0 0 1 1.4-.4A4.4 4.4 0 1 0 9 4.6v1.5c0 .4-.4.6-.7.4L5.6 4.4a.5.5 0 0 1 0-.8L8.3 1.5c.3-.2.7 0 .7.4z";
const FORWARD =
  "M9 3.2a5.8 5.8 0 1 0 5.6 7.3.7.7 0 0 0-1.4-.4A4.4 4.4 0 1 1 9 4.6v1.5c0 .4.4.6.7.4l2.7-2.1a.5.5 0 0 0 0-.8L9.7 1.5c-.3-.2-.7 0-.7.4z";

export interface ClioNowPlayingProps extends Omit<ClioTileProps, "children" | "label"> {
  label?: ReactNode;
  title?: string;
  /** Where it comes from, one mono line. */
  source?: ReactNode;
  /** Length in seconds. */
  duration?: number;
  /** Seconds in (controlled). */
  position?: number;
  defaultPosition?: number;
  onPositionChange?: (seconds: number) => void;
  playing?: boolean;
  defaultPlaying?: boolean;
  onPlayingChange?: (playing: boolean) => void;
  /** Seconds the back and forward buttons skip. */
  skip?: number;
  /** The cover; a ruled page with a ribbon by default. */
  art?: ReactNode;
  /** Three small level bars by the label while it plays. */
  levels?: boolean;
  playLabel?: string;
  pauseLabel?: string;
  backLabel?: (seconds: number) => string;
  forwardLabel?: (seconds: number) => string;
  seekLabel?: string;
}

export function ClioNowPlaying({
  label = "Listening",
  title = "The index card, explained",
  source = "Read aloud from your saves",
  duration = 700,
  position,
  defaultPosition = 252,
  onPositionChange,
  playing,
  defaultPlaying = true,
  onPlayingChange,
  skip = 15,
  art,
  levels = true,
  playLabel = "Play",
  pauseLabel = "Pause",
  backLabel = (s) => `Back ${s} seconds`,
  forwardLabel = (s) => `Forward ${s} seconds`,
  seekLabel = "Position",
  className,
  meta,
  ...tile
}: ClioNowPlayingProps) {
  const reduced = useClioReducedMotion();
  const [ownPlaying, setOwnPlaying] = useState(defaultPlaying);
  // Under reduced motion nothing starts moving by itself: it plays once someone presses play.
  const [byHand, setByHand] = useState(false);
  const isPlaying = playing ?? (ownPlaying && (!reduced || byHand));
  const [ownPosition, setOwnPosition] = useState(defaultPosition);
  const at = Math.min(Math.max(0, position ?? ownPosition), Math.max(0, duration));
  const [seeking, setSeeking] = useState(false);
  const trackRef = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);

  // The latest position and props, so one stable setter serves the frame loop, the keys and the buttons. The position
  // moves on as soon as it is set, so two ticks before a render still add up.
  const atRef = useRef(at);
  atRef.current = at;
  const latest = useRef({ controlled: position !== undefined, duration, onPositionChange });
  latest.current = { controlled: position !== undefined, duration, onPositionChange };
  const setAt = useCallback((seconds: number) => {
    const { controlled, duration: length, onPositionChange: report } = latest.current;
    const next = Math.min(Math.max(0, seconds), Math.max(0, length));
    atRef.current = next;
    if (!controlled) setOwnPosition(next);
    report?.(next);
  }, []);
  const setPlaying = (next: boolean) => {
    setByHand(true);
    if (playing === undefined) setOwnPlaying(next);
    onPlayingChange?.(next);
  };
  const stop = useRef(setPlaying);
  stop.current = setPlaying;

  // The playhead moves while it plays: smoothly frame by frame, or a step a second under reduced motion.
  useEffect(() => {
    if (!isPlaying || seeking) return;
    if (reduced) {
      const timer = setInterval(() => {
        const { position: next, ended } = clioAdvance(atRef.current, 1, duration);
        setAt(next);
        if (ended) stop.current(false);
      }, 1000);
      return () => clearInterval(timer);
    }
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const { position: next, ended } = clioAdvance(atRef.current, (now - last) / 1000, duration);
      last = now;
      setAt(next);
      if (ended) stop.current(false);
      else frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [isPlaying, seeking, reduced, duration, setAt]);

  useEffect(() => {
    const node = trackRef.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(([entry]) => setWidth(entry?.contentRect.width ?? 0));
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const fromPointer = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    return (
      (Math.min(Math.max(0, event.clientX - box.left), box.width) / Math.max(1, box.width)) *
      duration
    );
  };
  const onKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const step =
      event.key === "ArrowRight" || event.key === "ArrowUp"
        ? 5
        : event.key === "ArrowLeft" || event.key === "ArrowDown"
          ? -5
          : event.key === "PageUp"
            ? skip
            : event.key === "PageDown"
              ? -skip
              : null;
    if (step !== null) {
      event.preventDefault();
      setAt(at + step);
    } else if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      setAt(event.key === "Home" ? 0 : duration);
    }
  };

  const fraction = clioPlayhead(at, duration);
  return (
    <ClioTile
      {...tile}
      label={label}
      meta={
        meta ??
        (levels ? (
          <span className="clio-play__levels" aria-hidden="true">
            <i />
            <i />
            <i />
          </span>
        ) : null)
      }
      className={className ? `clio-play ${className}` : "clio-play"}
      data-playing={isPlaying ? "" : undefined}
    >
      <style>{CSS}</style>
      <div className="clio-play__body">
        <div className="clio-play__cover">{art ?? <ClioPaperCover title={title} />}</div>
        <div className="clio-play__main">
          <p className="clio-play__title">{title}</p>
          {source ? <p className="clio-caption">{source}</p> : null}
          <div
            ref={trackRef}
            className="clio-play__track"
            role="slider"
            tabIndex={0}
            aria-label={seekLabel}
            aria-valuemin={0}
            aria-valuemax={Math.round(duration)}
            aria-valuenow={Math.round(at)}
            aria-valuetext={`${clioFormatClock(at)} of ${clioFormatClock(duration)}`}
            data-seeking={seeking ? "" : undefined}
            onKeyDown={onKey}
            onPointerDown={(event) => {
              event.currentTarget.setPointerCapture(event.pointerId);
              setSeeking(true);
              setAt(fromPointer(event));
            }}
            onPointerMove={(event) => {
              if (seeking) setAt(fromPointer(event));
            }}
            onPointerUp={() => setSeeking(false)}
            onPointerCancel={() => setSeeking(false)}
            style={{
              ["--clio-play-at" as string]: fraction.toFixed(4),
              ["--clio-play-x" as string]: `${(fraction * width).toFixed(2)}px`,
            }}
          >
            <span className="clio-play__rail" aria-hidden="true">
              <span className="clio-play__fill" />
            </span>
            <span className="clio-play__head" aria-hidden="true" />
          </div>
          <p className="clio-caption clio-play__times" aria-hidden="true">
            <span>{clioFormatClock(at)}</span>
            <span>{clioFormatClock(duration)}</span>
          </p>
          <div className="clio-play__controls">
            <button
              type="button"
              className="clio-play__btn"
              aria-label={backLabel(skip)}
              onClick={() => setAt(at - skip)}
            >
              <Icon d={BACK} />
            </button>
            <button
              type="button"
              className="clio-play__btn"
              data-main=""
              aria-label={isPlaying ? pauseLabel : playLabel}
              onClick={() => setPlaying(!isPlaying)}
            >
              <Icon d={isPlaying ? PAUSE : PLAY} />
            </button>
            <button
              type="button"
              className="clio-play__btn"
              aria-label={forwardLabel(skip)}
              onClick={() => setAt(at + skip)}
            >
              <Icon d={FORWARD} />
            </button>
          </div>
        </div>
      </div>
    </ClioTile>
  );
}
